const execution = $json.execution || {};
const workflow = $json.workflow || {};
const sanitized = {
  correlation_id: $json.correlation_id || execution.id || crypto.randomUUID(),
  event_type: 'ERROR',
  workflow_name: workflow.name || null,
  node_name: $json.node?.name || null,
  error_type: $json.error?.name || 'Error',
  error_message: String($json.error?.message || 'Unknown error').replace(/(token|password|api[_-]?key)=\S+/ig, '$1=[redacted]'),
};
return [{ json: sanitized }];
